  "site.about.clubsEyebrow": "A rede",
  "site.about.clubsText": "Cada clube tem a sua casa e a sua comunidade, com a mesma coordenação técnica.",
  "site.about.clubsTitle": "Os nossos clubes",
  "site.about.heroText": "O Judo Arte e Vida nasceu no Algarve à volta de um treinador e de uma ideia: o judo é muito mais que um desporto.",
  "site.about.heroTitle": "Uma família à volta do tatami",
  "site.about.story1": "Tudo começa com Matias Luwawa, judoca desde 1994. Treinador desde 2006 e árbitro desde 2009, chegou a árbitro de elite e construiu, sala a sala, uma rede de clubes no Algarve: Lagos, Albufeira, Alvor.",
  "site.about.story2": "Hoje o Judo Arte e Vida reúne clubes, treinadores, atletas e famílias que partilham os mesmos valores, e uma plataforma que os liga: inscrições, quotas, presenças, provas e ranking num só lugar.",
  "site.about.storyEyebrow": "A nossa história",
  "site.about.storyTitle": "Do primeiro tatami a uma rede de clubes",
