  "site.values.title": "Arte, disciplina, vida",
  "site.vision.goalText": "É este o nosso objetivo: uma rede que cresce mantendo a mesma alma.",
  "site.vision.goalTitle": "Mais clubes, mais crianças no tatami, mais famílias envolvidas",
  "site.vision.heroText": "Queremos que cada criança, cada família e cada atleta encontre no judo disciplina, respeito e alegria: em qualquer clube da rede.",
  "site.vision.heroTitle": "O judo como escola de vida, ao alcance de todos",
  "site.vision.mission1": "O judo tem um código moral: respeito, sinceridade, coragem, autocontrolo. Levamo-lo do tatami para casa, para a escola, para a vida.",
  "site.vision.mission2": "E queremos que os clubes se possam dedicar a isto, não à burocracia: por isso a rede tem uma plataforma que trata sozinha de quotas, presenças, provas e contas.",
